            if '|' in m:
                cifra.append(m.split('|')[0].split()[0])
            else:
                cifra += [t for t in m.split()]
    return cifra
header,rows=load()
print('skipped-first-line:',header[:60])
print('rows loaded:',len(rows))
def cif(m): return [c.lower() for c in (limpa_cifra(m[8].split(';')) if m[8]!='' else [])]
cur=[set() for _ in range(6)]
for m in rows:
