    for i in range(6):
        if str(i) in toks: cur[i].add((m[0],m[1]))
print('CURRENT:',[len(s) for s in cur])
def contiguous_full(seq,c):
    n=len(seq); return any(c[i:i+n]==seq for i in range(len(c)-n+1))
def contiguous_dedup(seq,c):
    seen=set(); d=[]
    for x in c:
        if x not in seen: seen.add(x); d.append(x)
    n=len(seq); return any(d[i:i+n]==seq for i in range(len(d)-n+1))
def subset_any(seq,c): return set(seq).issubset(set(c))
def subsequence_ordered(seq,c):
    it=iter(c); return all(any(x==y for y in it) for x in seq)
def tag_semantics(seq,c): return contiguous_full(seq,c) and set(c).issubset(set(seq))
cands={'contiguous_full_ci':contiguous_full,'contiguous_dedup_ci':contiguous_dedup,'subset_any_ci':subset_any,'subsequence_ordered_ci':subsequence_ordered,'tag_semantics_ci':tag_semantics}
for name,fn in cands.items():
    res=[set() for _ in range(6)]
    for m in rows:
        c=cif(m)
        for i,seq in enumerate(SEQS):
            if fn(seq,c): res[i].add((m[0],m[1]))
    print(f'{name:26s} counts={[len(r) for r in res]} eq={[res[i]==cur[i] for i in range(6)]} extra={[len(res[i]-cur[i]) for i in range(6)]} missing={[len(cur[i]-res[i]) for i in range(6)]}')

# check multi-match rows in CSV tag
multi=[m for m in rows if len(m[7].replace(';',''))>1]
print('rows with >1 tag char in SEQ_FAMOSA:',len(multi), [(m[0],m[1],m[7]) for m in multi[:10]])

# Check: for current matches, is the sequence contiguous and is song chord-set subset?
for i,seq in enumerate(SEQS):
    ok_cont=ok_sub=ok_both=0
    for m in rows:
        if str(i) not in m[7].split(';'): continue
        c=cif(m)
        a=contiguous_full(seq,c); b=set(c).issubset(set(seq))
        ok_cont+=a; ok_sub+=b; ok_both+=(a and b)
    print('seq',i,'current',len(cur[i]),'contiguous',ok_cont,'subset',ok_sub,'both',ok_both)

# Show rows where subset_any_ci matches but current does not (for context on breadth)
for i,seq in enumerate(SEQS):
    extra=[(m[0],m[1],m[7],m[8][:80]) for m in rows if set(seq).issubset(set(cif(m))) and str(i) not in m[7].split(';')]
    print('seq',i,'subset_any_ci extra examples:',extra[:2],'total extra',len(extra))
